def req(method, path, body=None, token=None, key=None, raw_body=None, headers=None, ct="application/json"):
    url = BASE + path
    data = None
    if raw_body is not None:
        data = raw_body if isinstance(raw_body, bytes) else raw_body.encode()
    elif body is not None:
        data = json.dumps(body).encode()
    h = {"Content-Type": ct}
    if token: h["Authorization"] = "Bearer " + token
    if key is not None: h["Idempotency-Key"] = key
    if headers:
        for k, v in headers.items():
            if v is None: h.pop(k, None)
            else: h[k] = v
    r = urllib.request.Request(url, data=data, method=method, headers=h)
    try:
        with urllib.request.urlopen(r, timeout=10) as resp:
            raw = resp.read()
            try: parsed = json.loads(raw) if raw else None
            except Exception: parsed = raw.decode("utf-8", "replace")
            return resp.status, parsed
    except urllib.error.HTTPError as e:
