def handle_authorization_create(user, headers, body_raw):
    def execute(caller, body):
        with STORE.lock:
            state = STORE.state
            now_dt = datetime.now(timezone.utc)
            amount = parse_amount(body)
            note = parse_note(body)
            visibility = parse_visibility(body)
            to_handle = parse_string_field(body, "to_handle")
            to_user = state["users_by_handle"].get(to_handle)
            if to_user is None:
                err(404, "not_found", "no user has that handle")
            if to_user["id"] == caller["id"]:
                err(422, "self_payment", "cannot authorize to yourself")
            if Store.available_for(state, caller["id"], now_dt) < amount:
                err(409, "insufficient_funds",
                    "available balance is below the authorization amount")
            created_at = now_iso()
            expires_at = (Store.parse_ts(created_at)
                          + timedelta(seconds=state["authorization_ttl_seconds"])).isoformat()
            authz = {
                "authorization_id": new_id("a"),
                "from_user_id": caller["id"],
                "from_handle": caller["handle"],
                "to_user_id": to_user["id"],
                "to_handle": to_user["handle"],
                "amount": amount,
                "captured_amount": 0,
                "note": note,
                "visibility": visibility,
                "status": "open",
                "expires_at": expires_at,
                "payment_id": None,
                "payment_ids": [],
                "created_at": created_at,
            }
            state["authorizations"].append(authz)
            state["authorizations_by_id"][authz["authorization_id"]] = authz
            return 201, Store.authorization_receipt(state, authz)

    return idempotent_response("POST", "/authorizations", headers, body_raw, user, execute)


def handle_authorization_capture(user, authz_id, headers, body_raw):
    path = "/authorizations/%s/capture" % authz_id

    def execute(caller, body):
        with STORE.lock:
            state = STORE.state
            now_dt = datetime.now(timezone.utc)
            authz = state["authorizations_by_id"].get(authz_id)
            if authz is None:
                err(404, "not_found", "no such authorization")
            if authz["to_user_id"] != caller["id"]:
                err(403, "forbidden", "only the receiver may capture this authorization")
            was_open = authz["status"] == "open"
            open_now = Store.effective_open(state, authz, now_dt)
            if not open_now:
                if was_open:
                    err(409, "authorization_expired", "the authorization has expired")
                err(409, "authorization_not_open", "the authorization is no longer open")
            remaining = authz["amount"] - authz["captured_amount"]
            if "amount" in body and body["amount"] is not None:
                amount = parse_amount(body)
            else:
                amount = remaining
            if amount > remaining:
                err(422, "capture_exceeds_authorization",
                    "capture exceeds the remaining authorized amount")
            final = body.get("final", True)
            if not isinstance(final, bool):
                err(400, "malformed_request", "final must be a boolean")
            payer = state["users_by_id"][authz["from_user_id"]]
            receiver = state["users_by_id"][authz["to_user_id"]]
            payment = Store.move_money(state, payer, receiver, amount,
                                       authz["note"], authz["visibility"],
                                       request_id=None)
            payment["authorization_id"] = authz["authorization_id"]
            authz["captured_amount"] += amount
            authz["payment_ids"].append(payment["payment_id"])
            authz["payment_id"] = payment["payment_id"]
            if final or authz["captured_amount"] >= authz["amount"]:
                authz["status"] = "captured"
            return 201, Store.payment_receipt(state, payment)

    return idempotent_response("POST", path, headers, body_raw, user, execute)


def handle_authorization_void(user, authz_id):
    with STORE.lock:
        state = STORE.state
        caller = current_user(state, user)
        authz = state["authorizations_by_id"].get(authz_id)
        if authz is None:
            err(404, "not_found", "no such authorization")
        if authz["from_user_id"] != caller["id"]:
            err(403, "forbidden", "only the payer may void this authorization")
        Store.effective_open(state, authz, datetime.now(timezone.utc))
        if authz["status"] == "voided":
            return 200, Store.authorization_receipt(state, authz)
        if authz["status"] != "open":
            err(409, "authorization_not_open", "the authorization is no longer open")
        authz["status"] = "voided"
        return 200, Store.authorization_receipt(state, authz)


